Create a program in Java that takes a sentence as input and uses it to generate a list of the frequency of each word in the sentence. The program should output the list in descending order of frequency.

package myPackage;
import java.util.*;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
public class FrequencyCounter {
    public static Map<String, AtomicInteger> countWords(String sentence) {
        Map<String, AtomicInteger> wordCount = new HashMap<>();
        String[] words = sentence.split("\\s+");
        for (String word : words) {
            if (wordCount.containsKey(word)) {
                AtomicInteger count = wordCount.get(word);
                count.incrementAndGet();
            } else {
                wordCount.put(word, new AtomicInteger(1));
            }
        }
        return wordCount;
    }
    public static List<String> sortAscending(Map<String, AtomicInteger> wordCount) {
        List<String> sortedWords = new ArrayList(wordCount.keySet());
        sortedWords.sort(Comparator.comparingInt(wordCount::get));
        return sortedWords;
    }
    public static List<String> sortDescending(Map<String, AtomicInteger> wordCount) {
        List<String> sortedWords = new ArrayList(wordCount.keySet());
        sortedWords.sort(Comparator.comparingInt(wordCount::get).reversed());
        return sortedWords;
    }
    public static void main(String[] args) {
        String sentence = "a b c c a b a a b";
        Map<String, AtomicInteger> wordCount = countWords(sentence);
        List<String> sortedAscending = sortAscending(wordCount);
        List<String> sortedDescending = sortDescending(wordCount);
        System.out.println("Sorted ascending: " + sortedAscending);
        System.out.println("Sorted descending: " + sortedDescending);
    }}
